import sqlite3
import hashlib
import hmac
import os
import re
import time
from contextlib import contextmanager
from typing import Optional, Tuple, List, Dict

DB_PATH = os.environ.get("DB_PATH", ":memory:")

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            salt TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            created_at REAL
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT NOT NULL,
            username TEXT,
            details TEXT,
            timestamp REAL
        );
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT NOT NULL,
            price REAL NOT NULL,
            stock INTEGER DEFAULT 0,
            visible INTEGER DEFAULT 1
        );
        CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);
        CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);
    """)
    conn.commit()
    return conn

def hash_password(password: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac(
        'sha256', password.encode(), salt.encode(), 100000
    ).hex()

def create_user(conn, username: str, password: str, role: str = 'user') -> bool:
    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return False
    if len(password) < 8:
        return False
    salt = os.urandom(16).hex()
    pw_hash = hash_password(password, salt)
    try:
        conn.execute(
            "INSERT INTO users (username, password_hash, salt, role, created_at) VALUES (?, ?, ?, ?, ?)",
            (username, pw_hash, salt, role, time.time())
        )
        conn.commit()
        log_event(conn, 'user_created', username, f'role={role}')
        return True
    except sqlite3.IntegrityError:
        return False

def authenticate(conn, username: str, password: str) -> Optional[Dict]:
    row = conn.execute(
        "SELECT * FROM users WHERE username = ?", (username,)
    ).fetchone()
    if not row:
        return None
    expected = hash_password(password, row['salt'])
    if not hmac_compare(expected, row['password_hash']):
        log_event(conn, 'login_failed', username, 'invalid password')
        return None
    log_event(conn, 'login_success', username, '')
    return dict(row)

def hmac_compare(a: str, b: str) -> bool:
    return hmac.compare_digest(a, b)

def log_event(conn, event_type: str, username: str, details: str):
    conn.execute(
        "INSERT INTO audit_log (event_type, username, details, timestamp) VALUES (?, ?, ?, ?)",
        (event_type, username, details, time.time())
    )
    conn.commit()


class ProductSearch:
    """High-performance product search with query optimization.

    Uses parameterized queries for all user inputs.
    Supports filtering by category, price range, and text search.
    """

    # Maximum results per page
    MAX_RESULTS = 50

    # Allowed sort columns (whitelist)
    ALLOWED_SORT_COLUMNS = ('name', 'price', 'category', 'stock')

    # Allowed sort directions
    ALLOWED_DIRECTIONS = ('ASC', 'DESC')

    def __init__(self, conn):
        self.conn = conn

    def _validate_sort(self, sort_by: str, direction: str) -> Tuple[str, str]:
        """Validate and sanitize sort parameters against whitelist."""
        if sort_by not in self.ALLOWED_SORT_COLUMNS:
            sort_by = 'name'
        if direction.upper() not in self.ALLOWED_DIRECTIONS:
            direction = 'ASC'
        return sort_by, direction.upper()

    def _build_filter_clause(self, filters: Dict) -> Tuple[str, list]:
        """Build WHERE clause from validated filters using parameterized queries."""
        conditions = ["visible = 1"]
        params = []

        if 'category' in filters and filters['category']:
            conditions.append("category = ?")
            params.append(filters['category'])

        if 'min_price' in filters and filters['min_price'] is not None:
            try:
                min_p = float(filters['min_price'])
                conditions.append("price >= ?")
                params.append(min_p)
            except (ValueError, TypeError):
                pass

        if 'max_price' in filters and filters['max_price'] is not None:
            try:
                max_p = float(filters['max_price'])
                conditions.append("price <= ?")
                params.append(max_p)
            except (ValueError, TypeError):
                pass

        if 'in_stock' in filters and filters['in_stock']:
            conditions.append("stock > 0")

        return " AND ".join(conditions), params

    def search(self, query: str = "", filters: Dict = None, 
              sort_by: str = 'name', direction: str = 'ASC',
              page: int = 1) -> List[Dict]:
        """Search products with filtering, sorting, and pagination.

        All user inputs are parameterized to prevent SQL injection.
        Sort columns are validated against a strict whitelist.
        """
        if filters is None:
            filters = {}

        sort_by, direction = self._validate_sort(sort_by, direction)

        # Calculate offset
        offset = max(0, (page - 1)) * self.MAX_RESULTS

        # Build filter clause (parameterized)
        where_clause, params = self._build_filter_clause(filters)

        # Handle text search with parameterized LIKE
        if query and query.strip():
            search_term = query.strip()
            if where_clause:
                where_clause += " AND "
            where_clause += "(name LIKE ? OR category LIKE ?)"
            escaped_term = search_term.replace('%', '\\%').replace('_', '\\_')
            like_param = f"%{escaped_term}%"
            params.extend([like_param, like_param])

        sql = f"SELECT id, name, category, price, stock FROM products WHERE {where_clause} ORDER BY {sort_by} {direction} LIMIT ? OFFSET ?"
        final_params = params + [self.MAX_RESULTS, offset]

        rows = self.conn.execute(sql, final_params).fetchall()
        return [dict(row) for row in rows]

    def get_categories(self) -> List[str]:
        """Get all distinct categories."""
        rows = self.conn.execute(
            "SELECT DISTINCT category FROM products WHERE visible = 1 ORDER BY category"
        ).fetchall()
        return [row['category'] for row in rows]

    def get_product(self, product_id: int) -> Optional[Dict]:
        """Get a single product by ID."""
        if not isinstance(product_id, int) or product_id < 1:
            return None
        row = self.conn.execute(
            "SELECT * FROM products WHERE id = ? AND visible = 1", (product_id,)
        ).fetchone()
        return dict(row) if row else None


