import unittest

class TestProductSearch(unittest.TestCase):
    def setUp(self):
        self.conn = init_db()
        seed_products(self.conn)
        self.search = ProductSearch(self.conn)

    def test_basic_search(self):
        results = self.search.search(query="laptop")
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0]['name'], 'Laptop Pro 15')

    def test_category_filter(self):
        results = self.search.search(filters={'category': 'electronics'})
        self.assertEqual(len(results), 4)

    def test_price_range(self):
        results = self.search.search(filters={'min_price': 100, 'max_price': 500})
        self.assertTrue(all(100 <= r['price'] <= 500 for r in results))

    def test_sort_validation(self):
        # Invalid sort column should default to 'name'
        results = self.search.search(sort_by='DROP TABLE users; --')
        self.assertTrue(len(results) > 0)

    def test_pagination(self):
        page1 = self.search.search(page=1)
        self.assertTrue(len(page1) <= ProductSearch.MAX_RESULTS)

    def test_special_chars_in_search(self):
        # Should not cause SQL injection
        results = self.search.search(query="'; DROP TABLE products; --")
        self.assertEqual(len(results), 0)

    def test_sql_injection_in_category(self):
        # Category filter uses parameterized query
        results = self.search.search(filters={'category': "' OR 1=1 --"})
        self.assertEqual(len(results), 0)


class TestAuth(unittest.TestCase):
    def setUp(self):
        self.conn = init_db()

    def test_create_user(self):
        self.assertTrue(create_user(self.conn, 'testuser', 'password123'))

    def test_duplicate_user(self):
        create_user(self.conn, 'testuser', 'password123')
        self.assertFalse(create_user(self.conn, 'testuser', 'password456'))

    def test_invalid_username(self):
        self.assertFalse(create_user(self.conn, 'a', 'password123'))
        self.assertFalse(create_user(self.conn, 'user; DROP TABLE', 'password123'))

    def test_authenticate(self):
        create_user(self.conn, 'alice', 'securepass1')
        user = authenticate(self.conn, 'alice', 'securepass1')
        self.assertIsNotNone(user)
        self.assertEqual(user['username'], 'alice')

    def test_wrong_password(self):
        create_user(self.conn, 'bob', 'correctpass1')
        self.assertIsNone(authenticate(self.conn, 'bob', 'wrongpass'))


if __name__ == '__main__':
    unittest.main()
